{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "The inclusion criteria, based on the PICO framework, are as follows: ① Population: Patients with post-stroke depression (PSD) meeting the diagnostic criteria. ② Intervention: The experimental group includes TCE such as Tai Chi, Baduanjin, Yijinjing, and Wuqinxi, while the control group receives standard care, health education, or routine treatment. ③ Outcome: ... ④ Study Design: Only randomized controlled trials (RCTs) were included.",
      "reason": "Full PICO-based eligibility criteria including population, intervention/comparator, outcomes, and study design are explicitly specified, though setting and follow-up requirements are not detailed."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_28",
      "quote": "First, although both Chinese and English literature were screened, all included studies were in Chinese, likely because exercises such as Tai Chi and Qigong are unique to China.",
      "reason": "Language restrictions are implied (Chinese and English screened) in the Limitations, but dissemination year and publication status criteria are only partially inferable from exclusion criteria (e.g., dissertations, conference proceedings excluded); no explicit report-characteristics eligibility criteria (year, language, status) are stated in the methods."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "① Dissertations, conference proceedings, studies without full text access, or those with missing data. ... ④ Studies with outcome measures not aligned with the objectives of this research.",
      "reason": "Exclusion criteria distinguish studies with missing data/unavailable full text (results not reported/accessible) from studies whose outcome measures do not align with review objectives (outcomes not measured)."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "The experimental group includes TCE such as Tai Chi, Baduanjin, Yijinjing, and Wuqinxi, while the control group receives standard care, health education, or routine treatment.",
      "reason": "The synthesis groups (TCE intervention vs standard care/health education/routine treatment control) are defined within the PICO criteria and linked to the review objective of evaluating TCE effects on PSD; subgroup analysis is mentioned but subgroup groupings are not detailed, so this is at the lower bound of PRESENT."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PARTIAL",
      "chunk_id": "text_7",
      "quote": "Thus, the quest for an effective, safe, and easily implementable non-pharmacological treatment becomes imperative.",
      "reason": "A general rationale for focusing on TCE as a non-pharmacological intervention is provided in the background, but explicit rationales for specific restrictions such as excluding patients with comorbid malignancies or severe hepatic/renal dysfunction are not given."
    }
  ],
  "confidence": 82
}

